import React from 'react';
import Navbar from './components/common/Navbar';
import HeroSection from './components/home/HeroSection';
import CurationSection from './components/home/CurationSection';
import Footer from './components/common/Footer';

function App() {
  return (
    /* 💡 h-screen과 overflow-y-scroll, snap-y를 조합하면 전체 화면이 섹션 단위로 부드럽게 스크롤됩니다. */
    <div className="w-full min-h-screen bg-[#fbfbfa] text-zinc-900 overflow-x-hidden">
      <Navbar />
      
      {/* 각 섹션에 snap-start를 부여하여 스크롤 시 딱 맞아떨어지게 구성 가능 */}
      <div className="snap-start">
        <HeroSection />
      </div>
      
      <div className="snap-start">
        <CurationSection />
      </div>

      <Footer />
    </div>
  );
}

export default App;
